CREATE SET TABLE MDP01_META.META_INDEX ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      index_id INTEGER NOT NULL,      table_id INTEGER NOT NULL,      index_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      index_type VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      index_number INTEGER,      is_unique CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      is_clustered CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      comment_string VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      create_timestamp TIMESTAMP(6),      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( index_id );